//
//  PixelFaces.swift
//  ClickyCore
//
//  The Pixel faces as data: which lights are on in each frame of each state, and for how long. Generated from the
//  design's pixel.js by export.mjs, so the Mac app and the web UI can never drift apart. Do not edit by hand.
//
//  A row is 13 characters: "#" is a light at full brightness, "o" at half, "." is off.
//

import Foundation

public enum PixelState: String, CaseIterable, Sendable {
    case working, thinking, needs, failed, done, awake, talking, listening, idle, off

    /// When several are true at once, the earliest in this list is the face that shows.
    public static let priority: [PixelState] = [.off, .needs, .failed, .talking, .listening, .working, .thinking, .done, .awake, .idle]
    /// The colour of the lights, the chin light and the badge.
    public var hex: UInt32 {
        switch self {
        case .working: return 0x22D391
        case .thinking: return 0x22D391
        case .needs: return 0xFFD938
        case .failed: return 0xFF4A5E
        case .done: return 0xF4F4F5
        case .awake: return 0xC6C7D1
        case .talking: return 0xF4F4F5
        case .listening: return 0xF4F4F5
        case .idle: return 0x6E6E78
        case .off: return 0x3A3A41
        }
    }
    /// The word that goes with the face.
    public var label: String {
        switch self {
        case .working: return "Working"
        case .thinking: return "Thinking"
        case .needs: return "Needs you"
        case .failed: return "Failed"
        case .done: return "Done"
        case .awake: return "Ready"
        case .talking: return "Talking"
        case .listening: return "Listening"
        case .idle: return "Asleep"
        case .off: return "Off"
        }
    }
    /// States where a bot shows its own eyes. In the others every bot shows the same sign.
    public var usesOwnEyes: Bool { [.working, .thinking, .awake, .talking, .listening].contains(self) }
}

public struct PixelFrame: Sendable, Equatable {
    public let milliseconds: Int
    public let rows: [String]
}

public enum PixelFaces {
    public static let columns = 13
    public static let rows = 9
    public static let eyeStyles: [String] = ["block", "round", "tall", "wide", "heart"]

    /// The loop for a state. `eye` is the bot's eye style; it only matters where `usesOwnEyes` is true.
    public static func frames(_ state: PixelState, eye: String) -> [PixelFrame] {
        let table = table(state)
        return table[eye] ?? table["*"] ?? table["block"] ?? []
    }

    /// The frame on screen `elapsed` seconds into the loop.
    public static func frame(_ state: PixelState, eye: String, elapsed: Double) -> PixelFrame {
        let loop = frames(state, eye: eye)
        guard let first = loop.first else { return PixelFrame(milliseconds: 1000, rows: Array(repeating: String(repeating: ".", count: columns), count: rows)) }
        let total = loop.reduce(0) { $0 + $1.milliseconds }
        guard total > 0, elapsed.isFinite, elapsed > 0 else { return first }
        var at = Int((elapsed * 1000).truncatingRemainder(dividingBy: Double(total)))
        for frame in loop {
            if at < frame.milliseconds { return frame }
            at -= frame.milliseconds
        }
        return first
    }

    /// Below 22 points the screen shows one big sign on a 7 x 5 grid instead.
    public static func micro(_ state: PixelState) -> [String] {
        switch state {
        case .working: return [".......", ".##.##.", ".##.##.", ".##.##.", "......."]
        case .thinking: return [".......", ".##.##.", ".##.##.", ".......", ".#.#.#."]
        case .needs: return ["..###..", "....#..", "...#...", ".......", "...#..."]
        case .failed: return [".#...#.", "..#.#..", "...#...", "..#.#..", ".#...#."]
        case .done: return ["......#", ".....#.", "#...#..", ".#.#...", "..#...."]
        case .awake: return [".......", ".##.##.", ".##.##.", ".##.##.", "......."]
        case .talking: return [".##.##.", ".##.##.", ".......", ".#.#.#.", ".#####."]
        case .listening: return [".##.##.", ".##.##.", ".......", ".......", "#.#.#.#"]
        case .idle: return [".......", ".......", ".##.##.", ".......", "......."]
        case .off: return [".......", ".......", ".......", ".......", "......."]
        }
    }

    private static func table(_ state: PixelState) -> [String: [PixelFrame]] {
        switch state {
        case .working: return workingFrames
        case .thinking: return thinkingFrames
        case .needs: return needsFrames
        case .failed: return failedFrames
        case .done: return doneFrames
        case .awake: return awakeFrames
        case .talking: return talkingFrames
        case .listening: return listeningFrames
        case .idle: return idleFrames
        case .off: return offFrames
        }
    }

